'use client';

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react';
import { AnimatePresence, motion } from 'framer-motion';
import { CornerDownLeft, Loader2, SmilePlus, Trash2 } from 'lucide-react';
import Avatar from '@/components/ui/Avatar';
import { EmptyState } from '@/components/ui/Bits';
import { MessageCircle } from 'lucide-react';
import { api, normGroupMessage } from '@/lib/api';
import { getSocket } from '@/lib/socket';
import { firstName } from '@/lib/format';
import { useToast } from '@/components/ui/Toast';

/**
 * The group chat.
 *
 * What was here before was a list, not a chat: newest message printed at the
 * top, capped at twelve, no timestamps, and nothing arriving until the page
 * was reloaded. Every one of those is fixed here, and the fixes are what the
 * feature actually is — people will not stop using WhatsApp for a list.
 *
 * The same component serves two threads. With no `expenseId` it is the group
 * room; with one it is the comment thread on a single bill, which is where
 * "why is this ₹400?" belongs. The server keys messages the same way, so
 * there is one code path rather than two that drift.
 */

const QUICK_REACTIONS = ['👍', '😂', '🙏', '💸', '🔥'];

const sameDay = (a, b) =>
  new Date(a).toDateString() === new Date(b).toDateString();

function dayDivider(iso) {
  const d = new Date(iso);
  const today = new Date();
  const yesterday = new Date(today);
  yesterday.setDate(today.getDate() - 1);
  if (sameDay(d, today)) return 'Today';
  if (sameDay(d, yesterday)) return 'Yesterday';
  return d.toLocaleDateString(undefined, {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
  });
}

const clockTime = (iso) =>
  new Date(iso).toLocaleTimeString(undefined, { hour: 'numeric', minute: '2-digit' });

/** Group reactions by emoji so five thumbs render as one chip reading 5. */
function tallyReactions(reactions = [], meId) {
  const out = new Map();
  for (const r of reactions) {
    const row = out.get(r.emoji) || { emoji: r.emoji, count: 0, mine: false };
    row.count += 1;
    if (r.userId === meId) row.mine = true;
    out.set(r.emoji, row);
  }
  return [...out.values()];
}

function Bubble({ message, me, person, mine, showAuthor, onReact, onDelete }) {
  const [picking, setPicking] = useState(false);
  const reactions = tallyReactions(message.reactions, me.id);

  return (
    <motion.div
      layout="position"
      initial={{ opacity: 0, y: 8, scale: 0.98 }}
      animate={{ opacity: 1, y: 0, scale: 1 }}
      transition={{ type: 'spring', damping: 26, stiffness: 340 }}
      className={`flex w-full gap-2 ${mine ? 'justify-end' : 'justify-start'}`}
    >
      {/* The avatar column is held open even when the avatar is hidden, so a
          run of messages from one person stays on one vertical line. */}
      {!mine && (
        <span className="w-7 shrink-0 self-end">
          {showAuthor && <Avatar person={person} size="xs" />}
        </span>
      )}

      <div className={`flex min-w-0 max-w-[78%] flex-col ${mine ? 'items-end' : 'items-start'}`}>
        {showAuthor && !mine && (
          <span className="newq mb-1 px-1 text-[11px] text-ink-3">{firstName(person?.name)}</span>
        )}

        <button
          type="button"
          onClick={() => setPicking((v) => !v)}
          className={`group relative w-full rounded-[18px] px-3.5 py-2.5 text-left tap
            ${mine ? 'bg-brand text-on-brand' : 'bg-surface-2 text-ink'}
            ${mine ? 'rounded-br-[6px]' : 'rounded-bl-[6px]'}`}
        >
          <span className="newq block whitespace-pre-wrap break-words text-[14px] leading-snug">
            {message.text}
          </span>
          <span
            className={`newq mt-1 block text-[10.5px] ${mine ? 'text-on-brand/65' : 'text-ink-3'}`}
          >
            {clockTime(message.createdAt)}
          </span>
        </button>

        {reactions.length > 0 && (
          <div className="-mt-1.5 flex flex-wrap gap-1 px-1">
            {reactions.map((r) => (
              <button
                key={r.emoji}
                type="button"
                onClick={() => onReact(message.id, r.emoji)}
                className={`flex items-center gap-1 rounded-full px-2 py-0.5 text-[11px] tap
                  ${r.mine ? 'bg-brand-soft text-ink' : 'bg-surface-2 text-ink-2'}`}
              >
                <span>{r.emoji}</span>
                {r.count > 1 && <span className="num text-[10px]">{r.count}</span>}
              </button>
            ))}
          </div>
        )}

        <AnimatePresence>
          {picking && (
            <motion.div
              initial={{ opacity: 0, y: -4, scale: 0.95 }}
              animate={{ opacity: 1, y: 0, scale: 1 }}
              exit={{ opacity: 0, y: -4, scale: 0.95 }}
              transition={{ duration: 0.16 }}
              className="mt-1.5 flex items-center gap-1 rounded-full bg-surface px-1.5 py-1 shadow-[0_4px_18px_rgba(0,0,0,0.1)]"
            >
              {QUICK_REACTIONS.map((emoji) => (
                <button
                  key={emoji}
                  type="button"
                  aria-label={`React ${emoji}`}
                  onClick={() => {
                    onReact(message.id, emoji);
                    setPicking(false);
                  }}
                  className="grid size-7 place-items-center rounded-full text-[15px] tap hover:bg-surface-2"
                >
                  {emoji}
                </button>
              ))}
              {mine && (
                <button
                  type="button"
                  aria-label="Delete message"
                  onClick={() => {
                    onDelete(message.id);
                    setPicking(false);
                  }}
                  className="grid size-7 place-items-center rounded-full text-neg tap hover:bg-surface-2"
                >
                  <Trash2 size={13} strokeWidth={2.4} />
                </button>
              )}
            </motion.div>
          )}
        </AnimatePresence>
      </div>
    </motion.div>
  );
}

export default function ChatThread({
  groupId,
  expenseId = null,
  me,
  personById,
  initialMessages = null,
  initialHasMore = false,
  loading = false,
  emptyBody = 'Start with the bill everyone keeps asking about.',
  height = 'h-[52vh]',
}) {
  const { toast } = useToast();
  const [messages, setMessages] = useState(() =>
    initialMessages ? [...initialMessages].reverse() : [],
  );
  const [hasMore, setHasMore] = useState(initialHasMore);
  const [fetching, setFetching] = useState(!initialMessages);
  /** The `initialMessages` array this thread was last seeded from. */
  const [seed, setSeed] = useState(initialMessages);
  const [loadingMore, setLoadingMore] = useState(false);
  const [text, setText] = useState('');
  const [sending, setSending] = useState(false);

  const scrollRef = useRef(null);
  const bottomRef = useRef(null);
  /* Whether the reader is parked at the bottom. A message arriving while they
     are three screens up in the history must not yank them down. */
  const pinnedRef = useRef(true);

  /* Promise chain rather than async/await so every write happens inside a
     callback — the effect below subscribes, it does not set state on entry. */
  const loadFirstPage = useCallback(
    () =>
      api
        .groupMessages(groupId, expenseId ? `?expenseId=${expenseId}` : '')
        .then((out) => {
          setMessages((out.messages || []).map(normGroupMessage).reverse());
          setHasMore(!!out.hasMore);
          setFetching(false);
        })
        .catch(() => {
          /* Keep whatever is on screen; the composer still works. */
          setFetching(false);
        }),
    [groupId, expenseId],
  );

  /*
   * The parent already fetched the first page as part of the group's
   * engagement payload, so re-seed from it when it arrives rather than making
   * a second request for messages this component was handed. Adjusting state
   * during render — React's documented pattern for props-derived state — keeps
   * this out of an effect, which would render the empty list first and then
   * immediately replace it.
   */
  if (initialMessages && initialMessages !== seed) {
    setSeed(initialMessages);
    setMessages([...initialMessages].reverse());
    setHasMore(initialHasMore);
    setFetching(false);
  }

  useEffect(() => {
    if (initialMessages) return;
    loadFirstPage();
  }, [initialMessages, loadFirstPage]);

  /*
   * Realtime. The server sends only "something in this group's engagement
   * changed", so the thread re-reads its own first page rather than trusting a
   * payload — the same reasoning as the rest of the app's sync, and it means a
   * dropped socket message costs one wasted GET, never a missing reply.
   */
  useEffect(() => {
    const socket = getSocket();
    if (!socket) return undefined;
    const onSync = (payload) => {
      if (!payload?.scopes?.includes('engagement')) return;
      if (payload.groupId && payload.groupId !== groupId) return;
      if (payload.kind && payload.kind !== 'message') return;
      loadFirstPage();
    };
    socket.on('sync', onSync);
    return () => socket.off('sync', onSync);
  }, [groupId, loadFirstPage]);

  /* Stick to the bottom, but only when the reader was already there. */
  useLayoutEffect(() => {
    if (!pinnedRef.current) return;
    bottomRef.current?.scrollIntoView({ block: 'end' });
  }, [messages]);

  function onScroll(e) {
    const el = e.currentTarget;
    pinnedRef.current = el.scrollHeight - el.scrollTop - el.clientHeight < 60;
  }

  async function loadOlder() {
    if (loadingMore || !messages.length) return;
    setLoadingMore(true);
    const el = scrollRef.current;
    const before = el?.scrollHeight || 0;
    try {
      const params = new URLSearchParams({ before: messages[0].id });
      if (expenseId) params.set('expenseId', expenseId);
      const out = await api.groupMessages(groupId, `?${params}`);
      const older = (out.messages || []).map(normGroupMessage).reverse();
      setHasMore(!!out.hasMore);
      if (older.length) {
        pinnedRef.current = false;
        setMessages((prev) => [...older, ...prev]);
        /* Hold the reader's place: prepending changes scrollHeight, and
           without this the list jumps to a different message. */
        requestAnimationFrame(() => {
          if (el) el.scrollTop = el.scrollHeight - before;
        });
      }
    } catch (err) {
      toast({ tone: 'error', title: 'Could not load older messages', description: err.message });
    } finally {
      setLoadingMore(false);
    }
  }

  async function send(e) {
    e?.preventDefault();
    const body = text.trim();
    if (!body || sending) return;
    setSending(true);
    setText('');
    pinnedRef.current = true;
    try {
      const { message } = await api.createGroupMessage(groupId, { text: body, expenseId });
      setMessages((prev) => [...prev, normGroupMessage(message)]);
    } catch (err) {
      setText(body); // put the words back rather than losing them
      toast({ tone: 'error', title: 'Message not sent', description: err.message });
    } finally {
      setSending(false);
    }
  }

  async function react(messageId, emoji) {
    /* Optimistic: a reaction that waits for a round trip feels broken. */
    setMessages((prev) =>
      prev.map((m) => {
        if (m.id !== messageId) return m;
        const had = m.reactions.some((r) => r.userId === me.id && r.emoji === emoji);
        return {
          ...m,
          reactions: had
            ? m.reactions.filter((r) => !(r.userId === me.id && r.emoji === emoji))
            : [...m.reactions, { emoji, userId: me.id }],
        };
      }),
    );
    try {
      const { message } = await api.reactToMessage(groupId, messageId, emoji);
      setMessages((prev) => prev.map((m) => (m.id === messageId ? normGroupMessage(message) : m)));
    } catch {
      loadFirstPage();
    }
  }

  async function remove(messageId) {
    const snapshot = messages;
    setMessages((prev) => prev.filter((m) => m.id !== messageId));
    try {
      await api.deleteGroupMessage(groupId, messageId);
    } catch (err) {
      setMessages(snapshot);
      toast({ tone: 'error', title: 'Could not delete', description: err.message });
    }
  }

  /* Day dividers, and whether each bubble needs its author's name. A run of
     messages from one person inside two minutes reads as one turn. */
  const rows = useMemo(() => {
    const out = [];
    let lastDay = null;
    messages.forEach((m, i) => {
      const day = dayDivider(m.createdAt);
      if (day !== lastDay) {
        out.push({ kind: 'day', id: `day-${m.id}`, label: day });
        lastDay = day;
      }
      const prev = messages[i - 1];
      const sameAuthorRun =
        prev &&
        prev.authorId === m.authorId &&
        sameDay(prev.createdAt, m.createdAt) &&
        new Date(m.createdAt) - new Date(prev.createdAt) < 120000;
      out.push({ kind: 'msg', id: m.id, message: m, showAuthor: !sameAuthorRun });
    });
    return out;
  }, [messages]);

  const busy = loading || fetching;

  return (
    <div className="flex min-h-0 flex-col">
      <div
        ref={scrollRef}
        onScroll={onScroll}
        className={`${height} min-h-0 space-y-2.5 overflow-y-auto overscroll-contain px-0.5 pb-1`}
      >
        {busy ? (
          <div className="space-y-3 py-4">
            {[70, 45, 60].map((w, i) => (
              <div
                key={i}
                className={`h-10 animate-pulse rounded-[18px] bg-surface-2 ${i % 2 ? 'ml-auto' : ''}`}
                style={{ width: `${w}%` }}
              />
            ))}
          </div>
        ) : !messages.length ? (
          <EmptyState icon={MessageCircle} title="No messages yet" body={emptyBody} />
        ) : (
          <>
            {hasMore && (
              <div className="flex justify-center pb-1 pt-2">
                <button
                  type="button"
                  onClick={loadOlder}
                  disabled={loadingMore}
                  className="newq flex items-center gap-1.5 rounded-full bg-surface-2 px-3 py-1.5 text-[12px] text-ink-2 tap disabled:opacity-50"
                >
                  {loadingMore && <Loader2 size={12} className="animate-spin" />}
                  {loadingMore ? 'Loading' : 'Load earlier messages'}
                </button>
              </div>
            )}

            {rows.map((row) =>
              row.kind === 'day' ? (
                <div key={row.id} className="flex justify-center py-1.5">
                  <span className="newq rounded-full bg-surface-2 px-2.5 py-1 text-[10.5px] text-ink-3">
                    {row.label}
                  </span>
                </div>
              ) : (
                <Bubble
                  key={row.id}
                  message={row.message}
                  me={me}
                  person={personById(row.message.authorId)}
                  mine={row.message.authorId === me.id}
                  showAuthor={row.showAuthor}
                  onReact={react}
                  onDelete={remove}
                />
              ),
            )}
          </>
        )}
        <div ref={bottomRef} />
      </div>

      <form onSubmit={send} className="mt-3 flex items-end gap-2">
        <div className="flex min-w-0 flex-1 items-center rounded-[18px] bg-surface-2 px-3.5">
          <textarea
            value={text}
            rows={1}
            onChange={(e) => setText(e.target.value)}
            onKeyDown={(e) => {
              /* Enter sends, Shift+Enter breaks the line — the convention
                 every messaging app already taught these users. */
              if (e.key === 'Enter' && !e.shiftKey) send(e);
            }}
            placeholder={expenseId ? 'Ask about this bill' : 'Message the group'}
            maxLength={500}
            className="newq max-h-24 w-full resize-none bg-transparent py-3 text-[14.5px] text-ink outline-none placeholder:text-ink-3"
          />
        </div>
        <button
          type="submit"
          aria-label="Send message"
          disabled={!text.trim() || sending}
          className="grid size-11 shrink-0 place-items-center rounded-full bg-brand text-on-brand tap
            active:scale-95 disabled:opacity-35"
        >
          {sending ? (
            <Loader2 size={16} className="animate-spin" />
          ) : (
            <CornerDownLeft size={16} strokeWidth={2.5} />
          )}
        </button>
      </form>

      <p className="newq mt-2 flex items-center gap-1.5 px-1 text-[11px] text-ink-3">
        <SmilePlus size={11} strokeWidth={2.4} />
        Tap a message to react
      </p>
    </div>
  );
}
